// MethodTemplateName = CSharpInOut;
if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(inDom.OuterXml));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefPropertyUpdate|" + aml);
}
var input = inDom.DocumentElement ?? throw new Exception("Missing input");
bool initial = !input.HasAttribute("oldId");
var property = input.SelectSingleNode("fixed_ref") ?? throw new Exception("Missing property");
var previous = property.SelectSingleNode("Item") ?? throw new Exception("Missing child");
var number = previous.SelectSingleNode("item_number");
string expected = input.SelectSingleNode("note")?.InnerText ?? "";
eventData.BaseUpdateItem(outDom);
if (initial)
{
    var currentProperty = input.SelectSingleNode("fixed_ref");
    var current = currentProperty?.SelectSingleNode("Item");
    if (!Object.ReferenceEquals(property, currentProperty)
        || Object.ReferenceEquals(previous, current) || previous.ParentNode != null
        || !Object.ReferenceEquals(number, previous.SelectSingleNode("item_number"))
        || number?.InnerText != "TARGET-A"
        || property.Attributes["keyed_name"]?.Value != "Keep"
        || current?.SelectSingleNode("item_number")?.InnerText != expected)
    {
        throw new Exception("Property replacement lost native XML ownership");
    }
}

if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefPropertyBeforeVersion|" + aml);
}
var replacement = this.newItem("RefPropertyRecord", "get");
replacement.setProperty("item_number", this.getProperty("note"));
this.setPropertyItem("fixed_ref", replacement);
return this;
